1. Install Expo Router:
```
npm install expo-router
```

2. Create an `app` folder at the root of your project.

3. Update your `App.js`:
```js
import { ExpoRouter } from 'expo-router';
export default function App() {
  return <ExpoRouter />;
}
```

Create a file structure:
```
/app
  /index.js       -> '/'
  /about.js       -> '/about'
```
Example: `app/index.js`
```js
import { View, Text } from 'react-native';
export default function Home() {
  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>Home Screen</Text>
    </View>
  );
}
```
Example: `app/about.js`
```js
import { View, Text } from 'react-native';
export default function About() {
  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>About Screen</Text>
    </View>
  );
}
```

Create nested folders inside `app`:
```
/app
  /settings
    /index.js       -> '/settings'
    /profile.js     -> '/settings/profile'
```
`app/settings/index.js`
```js
import { View, Text } from 'react-native';
export default function Settings() {
  return <Text>Settings Screen</Text>;
}
```
`app/settings/profile.js`
```js
import { View, Text } from 'react-native';
export default function Profile() {
  return <Text>Profile Screen</Text>;
}
```

Use square brackets to create dynamic segments:
```
/app
  /user
    /[id].js   -> '/user/:id'
```
`app/user/[id].js`
```js
import { View, Text } from 'react-native';
import { useRouter, useLocalSearchParams } from 'expo-router';

export default function User() {
  const params = useLocalSearchParams();
  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>User ID: {params.id}</Text>
    </View>
  );
}
```

Use `Link` component or `useRouter` hook for navigation:
```js
import { View, Text, Button } from 'react-native';
import { Link, useRouter } from 'expo-router';

export default function Home() {
  const router = useRouter();

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>Home Screen</Text>
      <Link href="/about">
        <Text style={{ color: 'blue', marginTop: 20 }}>Go to About</Text>
      </Link>
      <Button title="Go to Profile" onPress={() => router.push('/settings/profile')} />
    </View>
  );
}
```
